{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.core_tshirts_availability AS WITH sku_list AS ( SELECT TRIM(UPPER(column1)) AS SKU_GROUP, TRIM(UPPER(column2)) AS SKU_FAMILY, column3 AS TYPE, column4 AS SUBTYPE FROM (VALUES (\'4PL002-01\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-02\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-03\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-04\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-05\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-06\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-07\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-08\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-09\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-10\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-11\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL003-01\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL003-02\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL003-03\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL003-04\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL003-05\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL003-06\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL004-01\',\'4PL004\',\'Polo\',\'Oversized Cotton\'), (\'4PL004-03\',\'4PL004\',\'Polo\',\'Oversized Cotton\'), (\'4PL011-01\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4PL011-02\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4PL011-03\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4PL011-04\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4PL011-05\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4PL011-06\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4RN001-01\',\'4RN001\',\'Sleeveless\',\'Sleeveless\'), (\'4RN001-02\',\'4RN001\',\'Sleeveless\',\'Sleeveless\'), (\'4RN001-03\',\'4RN001\',\'Sleeveless\',\'Sleeveless\'), (\'4RN001-04\',\'4RN001\',\'Sleeveless\',\'Sleeveless\'), (\'4RN001-05\',\'4RN001\',\'Sleeveless\',\'Sleeveless\'), (\'4RN002-01\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-02\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-03\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-04\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-05\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-06\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-07\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-08\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-09\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-10\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-11\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN003-01\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-02\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-03\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-04\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-05\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-06\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-07\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-08\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-09\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-10\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-11\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-12\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-13\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-14\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-15\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN005-01\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-02\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-03\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-04\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-05\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-06\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-07\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-08\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-09\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-10\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-11\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\') ) ), bp AS ( SELECT UPPER(TRIM(b.SKU_GROUP)) AS SKU_GROUP, b.TITLE, b.IMAGE_URL, b.ORIGINAL_PRICE, b.FINAL_SKU_CLASS, b.ONLINE_INVENTORY AS WH_INVENTORY, CASE WHEN b.FINAL_SKU_CLASS NOT IN (\'cut_tail\',\'cut_bad_belly\',\'cut_head\') OR b.FINAL_SKU_CLASS IS NULL THEN b.ONLINE_INVENTORY ELSE 0 END AS WH_INVENTORY_NON_CUT, CASE WHEN b.FINAL_SKU_CLASS IN (\'cut_tail\',\'cut_bad_belly\',\'cut_head\') THEN \'Yes\' ELSE \'No\' END AS IS_CUT_SKU FROM snitch_db.maplemonk.base_product b INNER JOIN sku_list s ON UPPER(TRIM(b.SKU_GROUP)) = s.SKU_GROUP ), sku_rollup AS ( SELECT UPPER(TRIM(o.SKU_GROUP)) AS SKU_GROUP, SUM(o.INVENTORY) AS TOTAL_STORE_INVENTORY, COUNT(DISTINCT o.BRANCH_CODE) AS TOTAL_STORES_MAPPED, COUNT(DISTINCT CASE WHEN o.INVENTORY > 0 THEN o.BRANCH_CODE END) AS STORES_WITH_STOCK, COUNT(DISTINCT CASE WHEN o.CUT_SIZE_FLAG = \'No\' AND o.INVENTORY > 0 THEN o.BRANCH_CODE END) AS STORES_HEALTHY_NON_CUT, SUM(o.FINAL_ROS) AS SUM_DAILY_ROS, AVG(CASE WHEN o.INVENTORY > 0 THEN o.FINAL_ROS END) AS AVG_ROS_PER_STOCKED_STORE FROM snitch_db.maplemonk.offline_master o INNER JOIN sku_list s ON UPPER(TRIM(o.SKU_GROUP)) = s.SKU_GROUP GROUP BY UPPER(TRIM(o.SKU_GROUP)) ) SELECT s.SKU_GROUP, s.SKU_FAMILY, s.TYPE, s.SUBTYPE, bp.TITLE, bp.IMAGE_URL, bp.ORIGINAL_PRICE AS MRP, bp.FINAL_SKU_CLASS, bp.IS_CUT_SKU, bp.WH_INVENTORY AS WH_INVENTORY, bp.WH_INVENTORY_NON_CUT AS WH_INVENTORY_NON_CUT, r.TOTAL_STORE_INVENTORY AS TOTAL_STORE_INVENTORY_ALL_STORES, (COALESCE(bp.WH_INVENTORY,0) + COALESCE(r.TOTAL_STORE_INVENTORY,0)) AS TOTAL_INVENTORY, r.TOTAL_STORES_MAPPED, r.STORES_WITH_STOCK, r.STORES_HEALTHY_NON_CUT, ROUND(r.SUM_DAILY_ROS, 2) AS SUM_DAILY_ROS_ALL_STORES, ROUND(r.AVG_ROS_PER_STOCKED_STORE, 3) AS AVG_ROS_PER_STOCKED_STORE, ROUND( (COALESCE(bp.WH_INVENTORY_NON_CUT,0) + COALESCE(r.TOTAL_STORE_INVENTORY,0)) / NULLIF(r.SUM_DAILY_ROS, 0) , 1) AS DOC_SYSTEM_WIDE, ROUND(COALESCE(bp.WH_INVENTORY_NON_CUT,0) / NULLIF(r.SUM_DAILY_ROS, 0), 1) AS DOC_WH_NON_CUT_SYSTEM, ROUND(COALESCE(r.TOTAL_STORE_INVENTORY,0) / NULLIF(r.SUM_DAILY_ROS, 0), 1) AS DOC_STORE_SYSTEM, o.BRANCH_CODE, o.MARKETPLACE_MAPPED AS STORE_NAME, o.CITY, o.STATE, o.REGION, o.CLUSTER, o.PARTNER, o.AM, o.RM, o.NSM, o.INVENTORY AS STORE_INVENTORY, o.FRESH_INVENTORY, o.JIT_QTY, o.NUM_SIZE_AVAILABLE AS SIZES_LIVE_AT_STORE, o.CUT_SIZE_FLAG, o.CUT_SIZE_WITH_JIT_FLAG, o.SKU_CLASS AS STORE_SKU_CLASS, o.VM_OPTION, o.BASE_STOCK, ROUND(o.FINAL_ROS, 3) AS DAILY_ROS_THIS_STORE, o.SALES_LAST_7_DAYS, o.SALES_LAST_15_DAYS, o.SALES_LAST_30_DAYS, o.TOTAL_SALES AS LIFETIME_SALES_THIS_STORE, ROUND(o.INVENTORY / NULLIF(o.FINAL_ROS, 0), 1) AS DOC_THIS_STORE, CASE WHEN o.CUT_SIZE_FLAG = \'Yes\' AND bp.WH_INVENTORY_NON_CUT > 0 THEN \'Replenish-able\' WHEN o.CUT_SIZE_FLAG = \'Yes\' AND COALESCE(bp.WH_INVENTORY_NON_CUT,0) = 0 THEN \'Cut + WH Empty\' WHEN o.CUT_SIZE_FLAG = \'No\' THEN \'Healthy\' ELSE \'Check\' END AS STORE_STATUS, o.XS_UNITS, o.S_UNITS, o.M_UNITS, o.L_UNITS, o.XL_UNITS, o.XXL_UNITS, o.XL3_UNITS, o.XL4_UNITS, o.XL5_UNITS, o.XL6_UNITS, o.JIT_XS_UNITS, o.JIT_S_UNITS, o.JIT_M_UNITS, o.JIT_L_UNITS, o.JIT_XL_UNITS, o.JIT_2XL_UNITS, o.JIT_3XL_UNITS, o.JIT_4XL_UNITS, o.JIT_5XL_UNITS, o.JIT_6XL_UNITS FROM sku_list s LEFT JOIN bp ON bp.SKU_GROUP = s.SKU_GROUP LEFT JOIN sku_rollup r ON r.SKU_GROUP = s.SKU_GROUP LEFT JOIN snitch_db.maplemonk.offline_master o ON UPPER(TRIM(o.SKU_GROUP)) = s.SKU_GROUP ORDER BY s.TYPE, s.SUBTYPE, s.SKU_GROUP, o.CLUSTER, o.BRANCH_CODE;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            